import SwiftUI

@MainActor final class NOVASwiftSocialNotifications:ObservableObject {
    @Published private(set) var topic=""
    @Published private(set) var preview=false
    @Published private(set) var status=""
    @Published private(set) var busy=false
    private var generation=0
    private let transport:NOVASwiftSocial.Transport
    init(transport:NOVASwiftSocial.Transport?=nil){self.transport=transport ?? {owner,path,method,body,query in try await NOVAAccountService(session:owner).request(path,method:method,body:body,query:query)}}
    func cancel(){generation+=1;topic="";status="";busy=false}
    func load(_ store:NOVASwiftStore) async {guard let state=store.archive?.active,let owner=NOVASession(state) else{status="Accedi al tuo account NOVA.";return};generation+=1;let expected=generation;do{let response=try await transport(owner,"profile","GET",nil,[]);guard expected==generation,store.archive.flatMap({NOVASession($0.active)})==owner else{return};guard response.object?["ok"]?.flag==true else{throw NOVAServiceError.invalidResponse};let profile=response.object?["profile"]?.object ?? [:];topic=profile["ntfy_topic"]?.string ?? "";preview=profile["privacy_msg"]?.flag != true;status=topic.isEmpty ? "Codice non presente online. Apri il profilo e salva le impostazioni notifiche.":"Codice letto dal server. Nessun test inviato."}catch{if expected==generation{status="Configurazione online non verificata."}}}
    func setPreview(_ enabled:Bool,_ store:NOVASwiftStore) async {guard !busy,let state=store.archive?.active,let owner=NOVASession(state) else{return};let expected=generation;busy=true;defer{if expected==generation{busy=false}};do{let response=try await transport(owner,"profile","PUT",.object(["privacy_msg":.number(enabled ? 0:1)]),[]);guard expected==generation,store.archive.flatMap({NOVASession($0.active)})==owner else{return};guard response.object?["ok"]?.flag==true else{throw NOVAServiceError.invalidResponse};try store.update(owner:store.archive!.owner){root in var profile=root["prof"]?.object ?? [:];profile["pvMsg"] = .number(enabled ? 1:0);root["prof"] = .object(profile)};preview=enabled;status="Anteprima aggiornata online."}catch{if expected==generation{status="Anteprima non modificata: salvataggio online non confermato."}}}
    func test(_ store:NOVASwiftStore) async {guard !busy,!topic.isEmpty,let state=store.archive?.active,let owner=NOVASession(state) else{return};let original=topic,expected=generation;busy=true;defer{if expected==generation{busy=false}};do{let response=try await transport(owner,"profile","GET",nil,[]);guard expected==generation,store.archive.flatMap({NOVASession($0.active)})==owner else{return};guard response.object?["ok"]?.flag==true,response.object?["profile"]?.object?["ntfy_topic"]?.string==original else{status="Codice cambiato online. Aggiorna la configurazione: nessun test inviato.";return};let test=try await transport(owner,"notifications/test","POST",.object([:]),[]);guard expected==generation,store.archive.flatMap({NOVASession($0.active)})==owner else{return};status=test.object?["ok"]?.flag==true ? "Test accettato dal server. Consegna sul dispositivo non verificata.":"Test non confermato dal server."}catch{if expected==generation{status="Test non confermato. Riprova."}}}
}
@MainActor struct NOVASwiftSocialNotificationSettings:View {
    @ObservedObject var store:NOVASwiftStore
    @StateObject private var model=NOVASwiftSocialNotifications()
    var body:some View {Form{Section("Avvisi sociali con ntfy"){Text("Non sono notifiche native APNs. Per riceverle serve configurare ntfy separatamente sul tuo dispositivo.").font(.footnote).foregroundStyle(.secondary);if !model.topic.isEmpty{Text(model.topic).font(.system(.body,design:.monospaced)).textSelection(.enabled);Button("Copia codice"){UIPasteboard.general.string=model.topic};Button("Invia test"){Task{await model.test(store)}}.disabled(model.busy);Toggle("Anteprima messaggi",isOn:Binding(get:{model.preview},set:{value in Task{await model.setPreview(value,store)}})).disabled(model.busy)};Button("Aggiorna dal server"){Task{await model.load(store)}};if !model.status.isEmpty{Text(model.status).font(.footnote)}}}.navigationTitle("Notifiche sociali").task{await model.load(store)}.onDisappear{model.cancel()}.onChange(of:store.archive?.owner){_,_ in model.cancel()}}
}
